package com.sentinelai.automation.api;
import com.sentinelai.automation.domain.*; import com.sentinelai.automation.infrastructure.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/playbooks") public class PlaybookController {
 private final PlaybookExecutionRepository executions; private final PlaybookApprovalRepository approvals;
 private static final Set<String> ACTIONS=Set.of("notify","open-ticket","request-step-up","simulated-block");
 public PlaybookController(PlaybookExecutionRepository e,PlaybookApprovalRepository a){executions=e;approvals=a;}
 @PostMapping("/{playbookId}/executions") public ResponseEntity<PlaybookExecution> request(@PathVariable String playbookId,@RequestBody ExecutionRequest r,Authentication auth){String tenant=tenant(auth); require(auth,"ROLE_ANALYST","ROLE_ADMIN"); if(!ACTIONS.contains(r.action())) throw bad("Action not allowed"); if(r.reason()==null||r.reason().isBlank()) throw bad("Reason is required"); var prior=executions.findByTenantIdAndIdempotencyKey(tenant,r.idempotencyKey()); if(prior.isPresent()) return ResponseEntity.ok(prior.get()); String impact=r.action().equals("simulated-block")?"HIGH":"MEDIUM"; var e=new PlaybookExecution(UUID.randomUUID(),tenant,playbookId,r.action(),impact,r.idempotencyKey(),auth.getName(),r.reason(),r.inputJson()==null?"{}":r.inputJson()); return ResponseEntity.status(HttpStatus.ACCEPTED).body(executions.save(e)); }
 @PostMapping("/executions/{id}/approvals") public PlaybookExecution approve(@PathVariable UUID id,@RequestBody ApprovalRequest r,Authentication auth){String tenant=tenant(auth); require(auth,"ROLE_ANALYST","ROLE_ADMIN","ROLE_AUDITOR"); var e=find(id,tenant); if(e.getRequester().equals(auth.getName())) throw bad("Requester cannot approve own execution"); if(!Set.of("APPROVE","REJECT").contains(r.decision())) throw bad("Invalid decision"); approvals.save(new PlaybookApproval(UUID.randomUUID(),id,tenant,auth.getName(),r.decision(),r.reason())); var all=approvals.findByExecutionIdAndTenantId(id,tenant); if("REJECT".equals(r.decision())) e.state("REJECTED",r.reason()); else if("HIGH".equals(e.getImpact())&&all.stream().filter(a->"APPROVE".equals(a.getDecision())).map(PlaybookApproval::getReviewer).distinct().count()>=2)e.state("APPROVED","Two independent approvals recorded"); else if("MEDIUM".equals(e.getImpact()))e.state("APPROVED","Human approval recorded"); return executions.save(e); }
 @PostMapping("/executions/{id}/run") public PlaybookExecution run(@PathVariable UUID id,Authentication auth){String tenant=tenant(auth); require(auth,"ROLE_ANALYST","ROLE_ADMIN"); var e=find(id,tenant); if(!"APPROVED".equals(e.getState())) throw bad("Execution requires approval"); e.state("SUCCEEDED","DRY_RUN: simulated action completed; no external side effect"); return executions.save(e); }
 private PlaybookExecution find(UUID id,String tenant){return executions.findById(id).filter(e->tenant.equals(e.getTenantId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 private void require(Authentication a,String... roles){if(Arrays.stream(roles).noneMatch(x->a.getAuthorities().stream().anyMatch(v->v.getAuthority().equals(x))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Insufficient role");}
 private String tenant(Authentication a){if(a instanceof JwtAuthenticationToken j){String t=j.getToken().getClaimAsString("tenant_id");if(t!=null&&!t.isBlank())return t;}throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant missing");}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
 public record ExecutionRequest(String action,String idempotencyKey,String reason,String inputJson){} public record ApprovalRequest(String decision,String reason){}
}
